using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using AlpineQuestPort;
class OptimizationTests {
    static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,Flags).GetValue(o);}
    static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Flags).Invoke(o,args);}
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS: "+text);}
    static void Pump(int ms){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(10);}}
    static void Shot(Form form,string path){using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(path);}}
    sealed class Server:IDisposable {
        readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);readonly Task task;public int Count,Conditional;public string Url;
        public Server(){listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/{z}/{x}/{y}.png";
            task=Task.Run(delegate{try{while(true)using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){
                var header=new StringBuilder();while(!header.ToString().EndsWith("\r\n\r\n")){int b=stream.ReadByte();if(b<0)break;header.Append((char)b);}Interlocked.Increment(ref Count);bool conditional=header.ToString().Contains("If-None-Match");if(conditional)Interlocked.Increment(ref Conditional);byte[] body;
                using(var b=new Bitmap(256,256))using(var memory=new MemoryStream()){using(var g=Graphics.FromImage(b))g.Clear(Color.Red);b.Save(memory,System.Drawing.Imaging.ImageFormat.Png);body=conditional?new byte[0]:memory.ToArray();}
                byte[] response=Encoding.ASCII.GetBytes("HTTP/1.1 "+(conditional?"304 Not Modified":"200 OK")+"\r\nCache-Control: max-age=0\r\nETag: \"tile\"\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(response,0,response.Length);stream.Write(body,0,body.Length);
            }}catch(SocketException){}catch(ObjectDisposedException){}});
        }
        public void Dispose(){listener.Stop();task.Wait(2000);}
    }
    static void Wait(TileStore store,int z,int x,int y){var until=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<until){using(var tile=store.GetTile(z,x,y)){if(tile!=null&&store.PendingCount==0)return;}Thread.Sleep(10);}throw new Exception("tile timeout: "+store.LastError);}
    static void Drain(TileStore store){var until=DateTime.UtcNow.AddSeconds(5);while(store.PendingCount>0&&DateTime.UtcNow<until)Thread.Sleep(10);Check(store.PendingCount==0,"network work drained");}
    static void Repeat(TileStore store,int z,int x,int y){for(int i=0;i<20;i++){using(var tile=store.GetTile(z,x,y)){}Thread.Sleep(10);}Drain(store);}
    static void Tile(string root,int z,int x,int y,Color color){string path=Path.Combine(root,z.ToString(),x.ToString(),y+".png");Directory.CreateDirectory(Path.GetDirectoryName(path));using(var image=new Bitmap(256,256)){using(var g=Graphics.FromImage(image))g.Clear(color);image.Save(path);}File.WriteAllText(path+".meta","0\n\"tile\"\n");}
    static void CacheTests(string output){using(var server=new Server()){
        var source=new MapSource{Id="test",Template=server.Url,Name="Local test",MinZoom=0,MaxZoom=20,DiskCache=true};string root=Path.Combine(output,"network");Tile(root,2,1,1,Color.Blue);
        using(var store=new TileStore(root,null,source)){store.OnlineEnabled=true;Wait(store,2,1,1);Repeat(store,2,1,1);Check(server.Count==0,"expired saved source tile: zero HTTP requests");store.OnlineEnabled=false;store.OnlineEnabled=true;Repeat(store,2,1,1);Check(server.Count==0,"online toggle: no saved-tile refresh");Wait(store,2,2,1);Repeat(store,2,2,1);Check(server.Count==1,"missing tile fetched once despite immediate HTTP expiry");Wait(store,3,2,1);Check(server.Count==2,"new zoom requires its own tile");store.RevalidateSaved=true;using(var image=store.GetTile(2,1,1)){}Drain(store);Check(server.Count==3&&server.Conditional==1,"explicit revalidation uses conditional HTTP");}
        using(var store=new TileStore(root,null,source)){store.OnlineEnabled=true;Wait(store,2,2,1);Repeat(store,2,2,1);Check(server.Count==3,"saved tile reused across store restart");}
        File.WriteAllText(Path.Combine(root,"2","2","1.png"),"broken");using(var store=new TileStore(root,null,source)){store.OnlineEnabled=true;Wait(store,2,2,1);Check(server.Count==4,"corrupt disk tile repaired from network");}
        string bundled=Path.Combine(output,"bundled");Directory.CreateDirectory(Path.Combine(bundled,"02"));using(var bitmap=new Bitmap(256,256))bitmap.Save(Path.Combine(bundled,"02","0_0.jpg"),System.Drawing.Imaging.ImageFormat.Jpeg);
        using(var store=new TileStore(Path.Combine(output,"fallback-cache"),bundled,source)){Wait(store,2,0,0);store.OnlineEnabled=true;Repeat(store,2,0,0);Check(server.Count==5,"packaged overview does not count as cached selected source");}
        var nonpersistent=source.Copy();nonpersistent.DiskCache=false;using(var store=new TileStore(root,null,nonpersistent)){store.OnlineEnabled=true;Wait(store,2,1,1);Check(server.Count==5,"existing cache readable even if new disk writes disabled");}
    }
        string cache=Path.Combine(output,"quota"),folder=Path.Combine(cache,"source");Tile(folder,2,0,0,Color.Blue);Tile(folder,2,0,1,Color.Red);File.SetLastWriteTimeUtc(Path.Combine(folder,"2","0","0.png"),DateTime.UtcNow.AddDays(-10));string user=Path.Combine(cache,"workspace.gpx");File.WriteAllText(user,"preserve");var before=TileCacheInventory.Scan(cache);Check(before.Count==2,"inventory counts only tile hierarchy");Check(TileCacheInventory.Trim(cache,0)==0&&File.Exists(Path.Combine(folder,"2","0","0.png")),"zero quota leaves cached tiles intact");TileCacheInventory.Trim(cache,1);Check(!File.Exists(Path.Combine(folder,"2","0","0.png"))&&File.Exists(Path.Combine(folder,"2","0","1.png"))&&File.ReadAllText(user)=="preserve","quota evicts old tile, protects recent tile and user document");
    }
    static MapDocument Fixture(){var d=new MapDocument();d.Waypoints.Add(new GeoPoint(50,35){Name="A",Group="G"});var t=new Track{Name="Route",IsRoute=true};t.Points.Add(new GeoPoint(50,35));t.Points.Add(new GeoPoint(51,36));d.Tracks.Add(t);var z=new Zone{Name="Area"};z.Points.AddRange(new[]{new GeoPoint(50,35),new GeoPoint(51,36),new GeoPoint(51,35)});d.Zones.Add(z);return d;}
    static void Imports(){var target=Fixture();var data=Fixture();data.Waypoints[0].ColorRgb=0xFF0000;data.Waypoints[0].Radio.HeightA=55;data.Zones[0].ColorRgb=1234;var plan=new ImportPlan(target,data);Check(plan.Duplicates==3&&plan.Apply(ImportPolicy.Skip)==0,"repeat import skips point, route and zone");var point=target.Waypoints[0];var history=new DocumentHistory();history.Reset(target);Check(new ImportPlan(target,data).Apply(ImportPolicy.Update)==3&&target.Waypoints[0].Radio.HeightA==55&&target.Zones[0].ColorRgb==1234&&Object.ReferenceEquals(point,target.Waypoints[0]),"update import keeps identity and changes properties");history.Record(target);Check(history.Move(false).Waypoints[0].Radio.HeightA!=55,"whole import undo restores properties");new ImportPlan(target,Fixture()).Apply(ImportPolicy.Copies);Check(target.Waypoints.Count==2&&target.Tracks.Count==2&&target.Zones.Count==2,"copy policy keeps intentional duplicates");data=Fixture();data.Waypoints[0].Lat+=.00001;Check(new ImportPlan(target,data).Duplicates==2,"same name at different coordinate is a new point");var empty=new MapDocument();data=Fixture();data.Waypoints.Add(data.Waypoints[0]);Check(new ImportPlan(empty,data).Duplicates==1&&new ImportPlan(empty,data).Apply(ImportPolicy.Skip)==3,"duplicates inside incoming file also skipped");}
    static void Ui(string output){using(var form=new MainForm(null,true,Path.Combine(output,"workspace"))){form.Show();Pump(80);var map=Field<MapCanvas>(form,"map");map.Settings.Elevation=false;map.Settings.Gpu=false;map.Document=Fixture();Call(form,"RefreshObjects");var tree=Field<TreeView>(form,"objects");var node=tree.Nodes[1].Nodes[0].Nodes[0];IntPtr handle=node.Handle;map.Document.Waypoints[0].Name="Renamed";Call(form,"RefreshObjects");Check(Object.ReferenceEquals(node,tree.Nodes[1].Nodes[0].Nodes[0])&&handle==node.Handle&&node.Text=="Renamed","single rename updates existing native node");
        map.Document.Waypoints.Clear();for(int i=0;i<20000;i++)map.Document.Waypoints.Add(new GeoPoint(50+i*.00001,35){Name="Point "+i,Group="Large"});var sw=Stopwatch.StartNew();Call(form,"RefreshObjects");Console.WriteLine("20k initial paged list ms="+sw.Elapsed.TotalMilliseconds.ToString("F2"));Check(tree.Nodes[1].Nodes[0].Nodes.Count==101,"large group creates first page, retains all 20000 objects");
        map.Document.Waypoints[0].Name="Edited";sw.Restart();Call(form,"RefreshObjects");Console.WriteLine("20k single rename ms="+sw.Elapsed.TotalMilliseconds.ToString("F2"));Call(form,"FocusObject",tree.Nodes[1].Nodes[0].Nodes[100].Tag);Check(tree.Nodes[1].Nodes[0].Nodes.Count==201,"next page is reachable");
        var search=Field<TextBox>(form,"objectSearch");search.Text="No match";search.Text="Point 19999";Pump(300);Check(tree.Nodes[1].Nodes[0].Nodes.Count==1&&tree.Nodes[1].Nodes[0].Nodes[0].Text=="Point 19999","debounced search covers unloaded pages");search.Clear();Pump(300);Call(form,"SelectMapPoint",map.Document.Waypoints[500]);Check(Object.ReferenceEquals(tree.SelectedNode.Tag,map.Document.Waypoints[500]),"map selection reveals point beyond first page");Shot(form,Path.Combine(output,"main.png"));
        using(var dialog=new MarkerDialog(map.Document.Waypoints[0])){dialog.Show();Pump(40);Check(Field<PointRadioEditor>(dialog,"radioEditor")==null&&dialog.ClientSize.Height<400,"radio preview stays unconstructed until requested");Shot(dialog,Path.Combine(output,"marker-compact.png"));dialog.Controls.OfType<Button>().First(button=>button.Text.StartsWith("Профиль и параметры")).PerformClick();Pump(30);Check(Field<PointRadioEditor>(dialog,"radioEditor")!=null&&dialog.ClientSize.Height>600,"radio section expands on demand");Shot(dialog,Path.Combine(output,"marker-expanded.png"));dialog.Close();}
        var sources=Field<List<MapSource>>(form,"sources");string cache=Path.Combine(output,"coverage");for(int x=4;x<12;x++)for(int y=4;y<9;y++)if(x!=7)Tile(Path.Combine(cache,sources[0].CacheKey),4,x,y,Color.Blue);
        using(var dialog=new MapCacheDialog(cache,sources,sources[0],0)){dialog.Show();Pump(300);Check(((Button)dialog.AcceptButton).Parent.ClientRectangle.Contains(((Button)dialog.AcceptButton).Bounds)&&Field<ComboBox>(dialog,"zoom").Parent.ClientRectangle.Contains(Field<ComboBox>(dialog,"zoom").Bounds),"cache controls remain inside dialog");Shot(dialog,Path.Combine(output,"cache.png"));dialog.Close();}
        using(var dialog=new ImportReviewDialog(new ImportPlan(Fixture(),Fixture()),"Мой маршрут.gpx")){dialog.Show();Pump(50);Shot(dialog,Path.Combine(output,"import.png"));dialog.Close();}form.Close();
    }}
    static void Gpu(){try{using(var gpu=new GpuPerspective())using(var tile=new Bitmap(256,256)){using(var tg=Graphics.FromImage(tile)){tg.Clear(Color.SteelBlue);tg.DrawEllipse(Pens.White,30,30,190,190);}Console.WriteLine("GPU renderer: "+gpu.Renderer);foreach(var size in new[]{new Size(1920,1080),new Size(2560,1440)})using(var bitmap=new Bitmap(size.Width,size.Height))using(var g=Graphics.FromImage(bitmap)){var read=new List<double>();var total=new List<double>();for(int i=0;i<35;i++){gpu.DrawScene(g,size.Width,size.Height,45,delegate(GpuPerspective context){for(int x=-256;x<size.Width+256;x+=256)for(int y=-256;y<size.Height+256;y+=256)context.DrawTile(tile,new RectangleF(x,y,256,256),new RectangleF(0,0,256,256));});if(i>=5){read.Add(gpu.ReadbackMilliseconds);total.Add(gpu.FrameMilliseconds);}}read.Sort();total.Sort();Console.WriteLine("GPU "+size.Width+"x"+size.Height+" readback incl GPU wait median="+read[15].ToString("F2")+" ms; raster frame median="+total[15].ToString("F2")+" ms");}}}catch(NotSupportedException ex){Console.WriteLine("GPU measurement unavailable: "+ex.Message);}}
    [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);CacheTests(output);Imports();Ui(output);Gpu();Console.WriteLine("PASS: optimization tests complete");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}

